<script>
(function(){
"use strict";
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const NS="http://www.w3.org/2000/svg";
function el(t,a,x){const e=document.createElementNS(NS,t);for(const k in a)e.setAttribute(k,a[k]);if(x!=null)e.textContent=x;return e;}
function cv(n){return getComputedStyle(document.body).getPropertyValue(n).trim();}

/* ===== 主题 / 进度 / 目录 ===== */
$("#tbtn").onclick=()=>{const c=document.documentElement.getAttribute("data-theme");
  document.documentElement.setAttribute("data-theme",c==="dark"?"light":"dark");draw1();draw2();};
const secs=$$("main section"),links=$$("#toc a:not(.sub)");
function onScroll(){const h=document.documentElement;
  $("#prog").style.width=(h.scrollTop/(h.scrollHeight-h.clientHeight)*100)+"%";
  let cur=secs[0].id;for(const s of secs)if(s.getBoundingClientRect().top<=120)cur=s.id;
  links.forEach(a=>a.classList.toggle("on",a.getAttribute("href")==="#"+cur));}
document.addEventListener("scroll",onScroll,{passive:true});onScroll();

/* ══════════════════════════════════════════════════════════════════════
   实验 1 · 时空图编辑器
   ══════════════════════════════════════════════════════════════════════ */
const NP=3, COLS=13, X0=78, X1=730, Y=[62,140,218], DX=(X1-X0)/(COLS-1);
const PC=["--s1","--s3","--s7"], PN=["P1","P2","P3"];
const E={list:[],next:1,mode:"ev",pend:null,sel:[]};
const xOf=t=>X0+t*DX;

function addLocal(p,t){ if(at(p,t))return null; const e={id:E.next++,p,t,kind:"local",link:0};E.list.push(e);return e; }
function at(p,t){ return E.list.find(e=>e.p===p&&e.t===t); }
function byId(i){ return E.list.find(e=>e.id===i); }
function removeEv(e){
  const ids=[e.id]; if(e.link) ids.push(e.link);
  E.list=E.list.filter(x=>!ids.includes(x.id));
  E.list.forEach(x=>{ if(x.link&&!byId(x.link)){x.link=0;x.kind="local";} });
  E.sel=E.sel.filter(i=>!ids.includes(i));
}
function computeClocks(){
  const ev=E.list.slice().sort((a,b)=>a.t-b.t||a.p-b.p);
  const L=[0,0,0], V=[[0,0,0],[0,0,0],[0,0,0]];
  ev.forEach(e=>{
    if(e.kind==="recv"){
      const s=byId(e.link);
      if(s&&s.L!=null){ L[e.p]=Math.max(L[e.p],s.L); for(let k=0;k<NP;k++)V[e.p][k]=Math.max(V[e.p][k],s.V[k]); }
    }
    L[e.p]++; V[e.p][e.p]++;
    e.L=L[e.p]; e.V=V[e.p].slice();
  });
}
function vLE(a,b){ for(let k=0;k<NP;k++) if(a[k]>b[k]) return false; return true; }
function vEq(a,b){ for(let k=0;k<NP;k++) if(a[k]!==b[k]) return false; return true; }
function relation(a,b){
  if(vEq(a.V,b.V)) return "same";
  if(vLE(a.V,b.V)) return "ab";
  if(vLE(b.V,a.V)) return "ba";
  return "conc";
}
function name(e){ return PN[e.p]+"@t"+e.t; }

function draw1(){
  computeClocks();
  const svg=$("#sv1"); svg.innerHTML="";
  const defs=el("defs",{});
  ["--s4","--ink-3"].forEach((c,i)=>{
    const m=el("marker",{id:"a1"+i,viewBox:"0 0 10 10",refX:9,refY:5,markerWidth:5,markerHeight:5,orient:"auto"});
    m.appendChild(el("path",{d:"M0,0 L10,5 L0,10 z",fill:cv(c)})); defs.appendChild(m);
  });
  svg.appendChild(defs);
  // 列刻度
  for(let t=0;t<COLS;t++){
    svg.appendChild(el("line",{x1:xOf(t),y1:Y[0]-26,x2:xOf(t),y2:Y[2]+26,stroke:cv("--grid"),"stroke-width":1,opacity:.55}));
    svg.appendChild(el("text",{x:xOf(t),y:Y[2]+44,fill:cv("--ink-3"),"font-size":9.5,"text-anchor":"middle","font-family":cv("--sans")},"t"+t));
  }
  // 进程线
  for(let p=0;p<NP;p++){
    svg.appendChild(el("line",{x1:X0-26,y1:Y[p],x2:X1+16,y2:Y[p],stroke:cv("--axis"),"stroke-width":2,"marker-end":"url(#a11)"}));
    svg.appendChild(el("text",{x:X0-38,y:Y[p]+5,fill:cv(PC[p]),"font-size":13,"font-weight":700,"text-anchor":"end","font-family":cv("--sans")},PN[p]));
  }
  // 消息箭头
  E.list.filter(e=>e.kind==="recv"&&byId(e.link)).forEach(e=>{
    const s=byId(e.link);
    svg.appendChild(el("line",{x1:xOf(s.t)+11,y1:Y[s.p]+(Y[e.p]>Y[s.p]?9:-9),x2:xOf(e.t)-9,y2:Y[e.p]+(Y[e.p]>Y[s.p]?-11:11),
      stroke:cv("--s4"),"stroke-width":1.8,"marker-end":"url(#a10)",opacity:.9}));
  });
  // 事件
  const showL=$("#c1lam").checked, showV=$("#c1vec").checked;
  E.list.forEach(e=>{
    const x=xOf(e.t),y=Y[e.p],selIdx=E.sel.indexOf(e.id);
    if(selIdx>=0) svg.appendChild(el("circle",{cx:x,cy:y,r:16,fill:"none",stroke:cv("--warn"),"stroke-width":2}));
    svg.appendChild(el("circle",{cx:x,cy:y,r:11,fill:cv(PC[e.p]),stroke:cv("--plane"),"stroke-width":2,style:"cursor:pointer"}));
    if(showL) svg.appendChild(el("text",{x:x,y:y+4,fill:"#fff","font-size":11,"font-weight":700,"text-anchor":"middle","font-family":cv("--sans"),style:"pointer-events:none"},e.L));
    if(showV) svg.appendChild(el("text",{x:x,y:y+27,fill:cv("--ink-3"),"font-size":9.5,"text-anchor":"middle","font-family":cv("--mono"),style:"pointer-events:none"},"["+e.V.join(",")+"]"));
    if(selIdx>=0) svg.appendChild(el("text",{x:x,y:y-19,fill:cv("--warn"),"font-size":10,"font-weight":700,"text-anchor":"middle","font-family":cv("--sans")},selIdx===0?"a":"b"));
    if(E.pend===e.id) svg.appendChild(el("circle",{cx:x,cy:y,r:19,fill:"none",stroke:cv("--s4"),"stroke-width":2,"stroke-dasharray":"3 3"}));
  });
  panel1();
}
function panel1(){
  const box=$("#rel1");
  if(E.sel.length<2){
    box.innerHTML='<div class="card-t">关系判定</div><p style="margin:0;font-size:13.5px;color:var(--ink-3)">'+
      (E.mode==="cmp"?"点击两个事件来比较它们。":"切到模式③「比较两个事件」，然后点任意两个事件。")+'</p>';
    return;
  }
  const a=byId(E.sel[0]),b=byId(E.sel[1]);
  if(!a||!b){E.sel=[];return;}
  const r=relation(a,b);
  const verdict={same:"同一个事件",ab:"<strong style='color:var(--ok)'>a → b</strong>（a happens-before b）",
    ba:"<strong style='color:var(--ok)'>b → a</strong>（b happens-before a）",
    conc:"<strong style='color:var(--crit)'>a ∥ b（并发）</strong> —— 谁都没有影响谁"}[r];
  const lam = a.L<b.L?"L(a) &lt; L(b) ⇒ Lamport 认为 a 在前"
            : a.L>b.L?"L(a) &gt; L(b) ⇒ Lamport 认为 b 在前"
            : "L(a) = L(b) ⇒ Lamport 无法区分";
  const misled = r==="conc" && a.L!==b.L;
  box.innerHTML='<div class="card-t">关系判定</div><dl class="rel">'+
    '<dt>事件 a</dt><dd><span class="chip">'+name(a)+'</span> Lamport <span class="vt">'+a.L+'</span>　向量 <span class="vt">['+a.V.join(",")+']</span></dd>'+
    '<dt>事件 b</dt><dd><span class="chip">'+name(b)+'</span> Lamport <span class="vt">'+b.L+'</span>　向量 <span class="vt">['+b.V.join(",")+']</span></dd>'+
    '<dt>向量时钟判定</dt><dd>'+verdict+'　<span style="color:var(--ink-3);font-size:13px">（充要，这是真相）</span></dd>'+
    '<dt>Lamport 判定</dt><dd>'+lam+'</dd></dl>'+
    (misled?'<div class="note crit" style="margin:12px 0 0"><div class="note-h"><span class="dot" style="background:var(--crit)"></span>抓到一个 Lamport 时钟的盲区</div><p style="margin-bottom:0">这两个事件<strong>实际是并发的</strong>，但它们的 Lamport 值一大一小。如果你据此认为「'+
      (a.L<b.L?name(a)+' 发生在 '+name(b)+' 之前':name(b)+' 发生在 '+name(a)+' 之前')+'」，你就错了——它们之间没有任何消息路径，谁都不可能影响谁。<br><em>这正是 §1.3 说的：Lamport 时钟只能证伪，不能证实。</em></p></div>':'')+
    (r==="ab"||r==="ba"?'<div class="note ok" style="margin:12px 0 0"><p style="margin-bottom:0">存在一条从 '+(r==="ab"?name(a)+" 到 "+name(b):name(b)+" 到 "+name(a))+' 的因果路径（沿着进程时间线和消息箭头走得通）。此时 Lamport 判定与向量时钟一致——<strong>有因果关系时两者永远不会矛盾</strong>。</p></div>':'');
}
// 坐标 → (p,t)
function hit(evt){
  const svg=$("#sv1"),pt=svg.createSVGPoint();
  pt.x=evt.clientX;pt.y=evt.clientY;
  const q=pt.matrixTransform(svg.getScreenCTM().inverse());
  let p=-1,best=1e9;
  Y.forEach((y,i)=>{const d=Math.abs(q.y-y);if(d<best&&d<34){best=d;p=i;}});
  const t=Math.round((q.x-X0)/DX);
  if(p<0||t<0||t>=COLS) return null;
  return {p,t};
}
$("#sv1").addEventListener("click",evt=>{
  const h=hit(evt); if(!h) return;
  const e=at(h.p,h.t);
  if(E.mode==="ev"){ if(!e) addLocal(h.p,h.t); }
  else if(E.mode==="del"){ if(e) removeEv(e); }
  else if(E.mode==="cmp"){ if(e){ E.sel=[...E.sel.filter(i=>i!==e.id),e.id].slice(-2); } }
  else if(E.mode==="msg"){
    if(E.pend==null){ if(e) E.pend=e.id; }
    else {
      const s=byId(E.pend);
      if(!s){E.pend=null;}
      else if(e||h.p===s.p||h.t<=s.t){ hintMsg(h,s,e); }
      else { const r={id:E.next++,p:h.p,t:h.t,kind:"recv",link:s.id};
             E.list.push(r); s.kind="send"; s.link=r.id; E.pend=null; }
    }
  }
  draw1(); updHint();
});
function hintMsg(h,s,e){
  const box=$("#h1");
  box.innerHTML='当前模式：<strong>发消息</strong> —— '+
    (e?'<span style="color:var(--crit)">目标格子已经有事件了，请选一个空位。</span>'
      :h.p===s.p?'<span style="color:var(--crit)">消息必须发给<strong>另一个</strong>进程。</span>'
      :'<span style="color:var(--crit)">接收时刻必须晚于发送时刻（t 要更大）。</span>');
}
function updHint(){
  const m={ev:'当前模式：<strong>加事件</strong> —— 在任意一条进程时间线的空位上点击，添加一个本地事件。',
    msg:E.pend?'当前模式：<strong>发消息</strong> —— 已选中发送方 <span class="chip">'+name(byId(E.pend))+'</span>，现在点<strong>另一个进程</strong>上一个更靠右的空位作为接收点。':
        '当前模式：<strong>发消息</strong> —— 先点一个已有事件作为发送方。',
    cmp:'当前模式：<strong>比较</strong> —— 依次点两个事件，下方面板会给出向量时钟判定与 Lamport 判定的对照。',
    del:'当前模式：<strong>删除</strong> —— 点击事件将其删除（成对的收发事件会一起删掉）。'}[E.mode];
  $("#h1").innerHTML=m;
}
$$("#m1 button").forEach(b=>b.onclick=()=>{
  $$("#m1 button").forEach(x=>x.classList.remove("act"));
  b.classList.add("act"); E.mode=b.dataset.m; E.pend=null;
  if(E.mode!=="cmp") E.sel=[];
  draw1(); updHint();
});
$("#c1lam").onchange=draw1; $("#c1vec").onchange=draw1;
$("#b1clr").onclick=()=>{E.list=[];E.next=1;E.pend=null;E.sel=[];draw1();updHint();};
$("#b1demo").onclick=()=>{
  E.list=[];E.next=1;E.pend=null;E.sel=[];
  const A=addLocal(0,1), Ev=addLocal(1,0), H=addLocal(2,2);
  const mk=(sp,st,rp,rt)=>{const s=addLocal(sp,st),r=addLocal(rp,rt);s.kind="send";s.link=r.id;r.kind="recv";r.link=s.id;};
  mk(0,3,1,5);   // P1 → P2
  mk(2,6,0,8);   // P3 → P1
  mk(1,7,2,9);   // P2 → P3
  addLocal(0,11); addLocal(2,12);
  draw1(); updHint();
};
$("#b1demo").click();
EOF
