/* ══════════════════════════════════════════════════════════════════════
   实验 2 · LWW 静默丢写 vs 版本向量
   ══════════════════════════════════════════════════════════════════════ */
const S2={played:false};
function p2(){ return {skew:+$("#r2o").value, gap:+$("#r2g").value}; }
function draw2(){
  const {skew,gap}=p2();
  $("#l2o").textContent=(skew>=0?"+":"")+skew+" ms";
  $("#l2g").textContent=gap+" ms";
  const svg=$("#sv2"); svg.innerHTML="";
  const W=700, L=96, R=660, T0=140, TB=1000;              // 真实时间轴 0..TB ms 映射到 L..R
  const xt=ms=>L+(ms/TB)*(R-L);
  const yA=52, yB=116, yAx=162;
  // 轴
  svg.appendChild(el("line",{x1:L,y1:yAx,x2:R,y2:yAx,stroke:cv("--axis"),"stroke-width":1.5}));
  for(let ms=0;ms<=TB;ms+=200){
    svg.appendChild(el("line",{x1:xt(ms),y1:yAx-4,x2:xt(ms),y2:yAx+4,stroke:cv("--axis")}));
    svg.appendChild(el("text",{x:xt(ms),y:yAx+18,fill:cv("--ink-3"),"font-size":9.5,"text-anchor":"middle","font-family":cv("--sans")},ms+"ms"));
  }
  svg.appendChild(el("text",{x:L,y:yAx+34,fill:cv("--ink-3"),"font-size":10,"font-family":cv("--sans")},"真实时间（上帝视角）"));
  // 副本行
  [[yA,"R1 · 副本一","--s1",skew],[yB,"R2 · 副本二","--s3",0]].forEach(r=>{
    svg.appendChild(el("line",{x1:L,y1:r[0],x2:R,y2:r[0],stroke:cv("--grid"),"stroke-width":1.5,"stroke-dasharray":"4 4"}));
    svg.appendChild(el("text",{x:L-10,y:r[0]+4,fill:cv(r[2]),"font-size":11.5,"font-weight":700,"text-anchor":"end","font-family":cv("--sans")},r[1]));
    svg.appendChild(el("text",{x:L-10,y:r[0]+18,fill:cv("--ink-3"),"font-size":9.5,"text-anchor":"end","font-family":cv("--mono")},"时钟 "+(r[3]>=0?"+":"")+r[3]+"ms"));
  });
  // 两次写
  const tA=T0, tB=T0+gap;
  const wr=(x,y,col,label,stamp,val)=>{
    svg.appendChild(el("line",{x1:x,y1:y,x2:x,y2:yAx,stroke:cv(col),"stroke-width":1,opacity:.45,"stroke-dasharray":"2 3"}));
    svg.appendChild(el("circle",{cx:x,cy:y,r:9,fill:cv(col),stroke:cv("--plane"),"stroke-width":2}));
    svg.appendChild(el("text",{x:x,y:y-16,fill:cv("--ink"),"font-size":11,"font-weight":640,"text-anchor":"middle","font-family":cv("--sans")},label));
    svg.appendChild(el("text",{x:x,y:y+4,fill:"#fff","font-size":10,"font-weight":700,"text-anchor":"middle","font-family":cv("--sans")},val));
    svg.appendChild(el("text",{x:x,y:y+24,fill:cv("--ink-3"),"font-size":9.5,"text-anchor":"middle","font-family":cv("--mono")},"打戳 "+stamp));
  };
  wr(xt(tA),yA,"--s1","C1 写入（先）",tA+skew,"A");
  wr(xt(tB),yB,"--s3","C2 写入（后）",tB,"B");
  // 结论
  const sA=tA+skew, sB=tB;
  const lwwWin = sA===sB ? "平局" : (sA>sB?"A":"B");
  const lost = lwwWin==="A" ? "B" : (lwwWin==="B"?null:"—");
